package com.gomgomapps.math.core;
import java.util.*;import org.junit.Test;import static org.junit.Assert.*;
public class LargeMentalDecompositionTest {
 private void verify(Question q){String[] words=q.prompt.split(" ");int a=Integer.parseInt(words[0]),b=Integer.parseInt(words[2]),result=words[1].equals("+")?a+b:a-b;boolean add=words[1].equals("+");q.answers=new String[]{"poison"};q.expression="poison";Checker c=new Checker();assertTrue(c.check(q,List.of(),List.of(""+result)).correct());assertEquals(Checker.Status.WRONG_ANSWER,c.check(q,List.of(),List.of(""+(result+1))).status);HelpPlan h=HelpPlan.forQuestion(q);assertFalse(h.canTransfer());assertTrue(h.restore(null,q.id).entries.stream().allMatch(String::isEmpty));int stage=0,running=a;assertTrue(h.step(stage++).accepts(""+a));for(int power=100000;power>=1;power/=10){int part=b/power%10*power;if(part==0)continue;assertTrue(h.step(stage++).accepts(""+part));running+=add?part:-part;assertTrue(running>=0);assertTrue(h.step(stage++).accepts(""+running));}assertEquals(result,running);assertEquals(stage,h.size());for(int i=0;i<h.size();i++)assertFalse(h.step(i).before.matches(".*[0-9].*"));}
 @Test public void actualLargePublicArithmeticAndEveryBlankSubtotal(){for(String id:List.of(LargeMentalDecomposition.ADD,LargeMentalDecomposition.SUB)){CurriculumLimits limits=GlobalCurriculum.limits("england-primary-2021-v1",id,5);assertTrue(limits.allows(LargeMentalDecomposition.make(id,500784,8000)));Generator g=new Generator(new Random(158));List<String> recent=new ArrayList<>();for(int i=0;i<300;i++){Question q=g.next(id,recent,false,limits);assertFalse(recent.contains(q.signature()));recent.add(q.signature());assertTrue(q.choices.isEmpty());verify(q);}}for(int[] operands:new int[][]{{1000,1000},{999999,999999},{100000,99999},{909090,80808},{999999,100001}})for(String id:List.of(LargeMentalDecomposition.ADD,LargeMentalDecomposition.SUB))verify(LargeMentalDecomposition.make(id,operands[0],operands[1]));}
 @Test public void smallDomainsExhaustAndLongRowsHaveCorrectBoundaries(){for(String id:List.of(LargeMentalDecomposition.ADD,LargeMentalDecomposition.SUB)){int count=id.equals(LargeMentalDecomposition.ADD)?225:120;assertEquals(count,LargeMentalDecomposition.count(id,1014));CurriculumLimits limits=new CurriculumLimits("wholeDigits=4;secondDigits=4;minGiven=1000;maxGiven=1014;maxResult=2028;nonnegative=true");Generator g=new Generator(new Random(158));List<String> recent=new ArrayList<>();for(int i=0;i<count;i++){Question q=g.next(id,recent,false,limits);assertFalse(recent.contains(q.signature()));recent.add(q.signature());verify(q);}assertEquals(recent.get(0),g.next(id,recent,false,limits).signature());}long size=999000;assertEquals(998001000000L,LargeMentalDecomposition.count(LargeMentalDecomposition.ADD,999999));assertEquals(499000999500L,LargeMentalDecomposition.count(LargeMentalDecomposition.SUB,999999));for(long row:new long[]{0,1,14,999,9999,499500,998999}){long start=row*(row+1)/2;int[] left=LargeMentalDecomposition.read(LargeMentalDecomposition.indexed(LargeMentalDecomposition.SUB,999999,start));assertEquals(1000+row,left[0]);assertEquals(1000,left[1]);int[] right=LargeMentalDecomposition.read(LargeMentalDecomposition.indexed(LargeMentalDecomposition.SUB,999999,start+row));assertEquals(right[0],right[1]);verify(LargeMentalDecomposition.indexed(LargeMentalDecomposition.SUB,999999,start+row));}int[] last=LargeMentalDecomposition.read(LargeMentalDecomposition.indexed(LargeMentalDecomposition.ADD,999999,size*size-1));assertArrayEquals(new int[]{999999,999999,1999998},last);}
 @Test public void malformedPublicOperandsAndWrongOperationCannotUseHiddenKeys(){for(String text:List.of("999 + 1000","1000 + 1000000","1000 + 1","1000 + 1000 = 2000","0010 + 1000","-1000 + 1000")){Question q=LargeMentalDecomposition.make(LargeMentalDecomposition.ADD,1000,1000);q.prompt=text;assertNull(LargeMentalDecomposition.read(q));assertEquals(Checker.Status.INPUT_NEEDED,new Checker().check(q,List.of(),List.of("2000")).status);}Question q=LargeMentalDecomposition.make(LargeMentalDecomposition.SUB,1000,1000);q.prompt="1000 + 1000";assertNull(LargeMentalDecomposition.read(q));assertFalse(Curriculum.inCurriculum(Catalog.get(LargeMentalDecomposition.ADD),2022));}
}
